/// <summary>
/// Handles the OnModified event of the METCreateDutyCredit field on the ReturnReasonCode form. If METCreateDutyCredit is set to true, then the METDispositionCodeId field is set to mandatory. If METCreateDutyCredit is set to false, then the METDispositionCodeId field is set to not mandatory.
/// </summary>
/// <param name="sender">metCreditDuty</param>
/// <param name="e">e</param>
[FormDataFieldEventHandler(formDataFieldStr(ReturnReasonCode, ReturnReasonCode, METCreateDutyCredit), FormDataFieldEventType::Modified)]
public static void METCreateDutyCredit_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    ReturnReasonCode returnReasonCode = sender.datasource().cursor() as ReturnReasonCode;
    if (returnReasonCode.METCreateDutyCredit)
    {
        sender.datasource().object(fieldNum(ReturnReasonCode, METDispositionCodeId)).mandatory(true);
    }
    else
    {
        sender.datasource().object(fieldNum(ReturnReasonCode, METDispositionCodeId)).mandatory(false);
    }
}

/// <summary>
/// on the activated event of the ReturnReasonCode form, check the value of METCreateDutyCredit field and set the METDispositionCodeId field to mandatory or not mandatory accordingly.
/// </summary>
/// <param name="sender">dataSource</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(ReturnReasonCode, ReturnReasonCode), FormDataSourceEventType::Activated)]
public static void ReturnReasonCode_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    ReturnReasonCode returnReasonCode = sender.cursor() as ReturnReasonCode;
    if (returnReasonCode.METCreateDutyCredit)
    {
        sender.object(fieldNum(ReturnReasonCode, METDispositionCodeId)).mandatory(true);
    }
    else
    {
        sender.object(fieldNum(ReturnReasonCode, METDispositionCodeId)).mandatory(false);
    }
}
